INSERT INTO 
	웹장바구니 
		(
			일자
			, 일련번호
			, 거래처코드
			, 단가사업장
			, 품목코드
			, 단가단위
			, 단가단위문자
			, 수량
			, 그룹수량
			, 낱개수량
			, 중량
			, 단가
			, 공급가액
			, 부가세
			, 합계금액
			, 납기일자
			, 착지업체
			, 출고사업장
			, 등록자
			, 등록일자
			, 등록시간
			, 수정자
			, 수정일자
			, 수정시간
		)
	VALUES
		(	#{oDate} 
			, (SELECT ISNULL(MAX(일련번호+1),1) FROM 웹장바구니 WHERE 1=1 AND 일자 = #{oDate}) 
			, #{bcncCode} 
			, #{item.oUnitBplc} 
			, #{item.itemCode}	 
			, #{item.oUntpcUnit}	
			, #{item.oUnitChrctr}	
			, #{item.oQuantity} 
			, #{item.oGrpQy} 
			, #{item.oPieceQy} 
			, #{item.oWt} 
			, #{item.oNewUnitpc} 
			, #{item.oSplpcAm} 
			, #{item.oVat} 
			, #{item.oSumAm} 
			, #{item.oDedt} 
			, #{item.dlvyEntrps} 




						, #{registBplc}



						, (SELECT CASE WHEN LEN(제조사업장) > 0 THEN 제조사업장 ELSE '20' END FROM 품목제조사업장 WHERE 품목코드 = #{item.itemCode})




			, #{bcncCode} 
			, CONVERT(VARCHAR,GETDATE(),112) 
			, REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','') 
			, #{bcncCode} 
			, CONVERT(VARCHAR,GETDATE(),112) 
			, REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','') 
		)
